"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('convolution-lab'))return;L.init(['duration','time'],()=>{const T=L.range('duration'),t=L.range('time'),end=Math.min(t,T),f=z=>z<=T?-Math.expm1(-z):Math.expm1(T)*Math.exp(-z),exact=f(t),N=8,dt=end/N,approx=Array.from({length:N},(_,i)=>Math.exp(-(t-(i+.5)*dt))*dt).reduce((a,b)=>a+b,0),g=L.$('drawing');g.replaceChildren();const a=L.svg('g'),b=L.svg('g',{transform:'translate(0,275)'});g.append(a,b);const axes=L.plot(a,[{fn:z=>z<=end?Math.exp(-(t-z)):0,color:'#cf604b'}],{xMax:2,yMin:0,yMax:1.1,height:270,xLabel:'發生輸入的時刻 τ（s）',yLabel:'目前還留下的貢獻密度（s⁻¹）'});if(end>0)for(let i=0;i<N;i++){const z=(i+.5)*dt,y=Math.exp(-(t-z));a.append(L.svg('rect',{x:axes.X(i*dt),y:axes.Y(y),width:axes.X(dt)-axes.X(0),height:axes.Y(0)-axes.Y(y),fill:'#cf604b22',stroke:'#cf604b','stroke-width':1}));}const bx=L.plot(b,[{fn:f}],{xMax:4,yMin:0,yMax:1.1,height:270,yLabel:'累積輸出 y（無量綱）'});b.append(L.svg('circle',{cx:bx.X(t),cy:bx.Y(exact),r:5,fill:'#172a45'}));L.text('result-primary',L.fmt(exact,6));L.text('result-secondary',L.fmt(approx,6));L.text('feedback','只加總 τ=0 到 '+L.fmt(end)+' s 的輸入，每個小面積再依距今多久乘上衰減。'+(t>T?'輸入已在 '+L.fmt(T)+' s 停止，但較早的回應還留著尾巴。':t===T?'輸入在此刻停止，新的輸入已為零，已有的貢獻仍留下尾巴。':t===0?'尚未累積任何時間，輸出為零。':'輸入仍在持續，舊貢獻衰減、新貢獻加入。')+' 右側近似用 8 個中點矩形，精確值用積分；兩者差 '+L.fmt(Math.abs(approx-exact),6)+'，不能把有限小格直接叫精確脈衝。');});})();
